mapper.select:
SELECT c.id, c.article_id AS articleId, c.user_id AS userId, c.content, c.parent_id AS parentId, c.like_count AS likeCount, c.create_time AS createTime, u.nickname AS userNickname, u.avatar AS userAvatar, CASE WHEN #{userId} IS NOT NULL THEN EXISTS(SELECT 1 FROM comment_like cl WHERE cl.comment_id = c.id AND cl.user_id = #{userId}) ELSE FALSE END AS liked FROM comment c LEFT JOIN `user` u ON c.user_id = u.id WHERE c.article_id = #{articleId}
ORDER BY CASE WHEN c.parent_id = 0 OR c.parent_id IS NULL THEN 0 ELSE 1 END ASC, IFNULL(c.like_count, 0) DESC, c.create_time DESC
ORDER BY CASE WHEN c.parent_id = 0 OR c.parent_id IS NULL THEN 0 ELSE 1 END ASC, c.create_time DESC
